<?php
/** Purpose-limited, school-operated prepaid ledger; no transfers or cash withdrawals. */
if(!defined('SCHOOLOS_INSIGHTS_LIBRARY')){header('Location: index.php?s=intelligence&area=wallet');exit;}
function dw_schema():array{return [
"CREATE TABLE IF NOT EXISTS dw_accounts(tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,balance_kobo BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS dw_controls(tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,guardian_id BIGINT UNSIGNED NOT NULL,allow_meals TINYINT NOT NULL,allow_store TINYINT NOT NULL,daily_limit_kobo BIGINT NOT NULL,PRIMARY KEY(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS dw_entries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,amount_kobo BIGINT NOT NULL,reference VARCHAR(100) NOT NULL,metadata_json TEXT NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(tenant_id,reference),KEY(tenant_id,student_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS dw_topups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,requested_by BIGINT UNSIGNED NOT NULL,amount_kobo BIGINT NOT NULL,provider VARCHAR(20) NOT NULL,reference VARCHAR(100) NOT NULL,bank_reference VARCHAR(120) NULL,checkout_url TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',confirmed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(tenant_id,reference),UNIQUE KEY(tenant_id,bank_reference)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS dw_menu(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,price_kobo BIGINT NOT NULL,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function dw_enabled(int $tid):void{if(!ix_setting($tid,'wallet_enabled'))throw new RuntimeException('School prepaid credits require explicit accounting, privacy and provider review and activation.');}
function dw_scope(array $u,int $sid):array{if(in_array($u['role'],['parent','student'],true))return op_child($u,$sid);ix_need($u,'wallet_cashier');return sv_own('students',$u,$sid);}
function dw_account(int $tid,int $sid):array{q('INSERT IGNORE INTO dw_accounts(tenant_id,student_id) VALUES(?,?)',[$tid,$sid]);return q('SELECT * FROM dw_accounts WHERE tenant_id=? AND student_id=? FOR UPDATE',[$tid,$sid])->fetch();}
function dw_credit(array $u,int $id,?callable $api=null):string{$tid=(int)$u['tenant_id'];dw_enabled($tid);$top=ix_own('dw_topups',$u,$id);dw_scope($u,(int)$top['student_id']);if($top['provider']==='bank'){if($u['role']!=='school_admin'||(int)$top['requested_by']===(int)$u['id'])throw new RuntimeException('A different school administrator must verify the actual bank receipt.');$bank=ix_key(op_text('bank_reference',120,true),120);}else{if($top['status']==='confirmed')return 'Top-up already confirmed.';$api??='fn45Api';$res=$api('GET','/transaction/verify/'.rawurlencode($top['reference']),fn45Secret($tid));$d=$res['data']??[];if(empty($res['status'])||($d['status']??'')!=='success'||($d['currency']??'')!=='NGN'||($d['reference']??'')!==$top['reference']||(int)($d['amount']??0)!==(int)$top['amount_kobo'])throw new RuntimeException('Paystack has not verified the exact NGN amount and reference.');$bank=null;}
return sv_tx(function()use($u,$tid,$id,$bank){$t=ix_own('dw_topups',$u,$id,true);if($t['status']==='confirmed')return 'Top-up already confirmed.';if($t['status']!=='pending')throw new RuntimeException('Top-up is not pending.');dw_account($tid,(int)$t['student_id']);q('INSERT INTO dw_entries(tenant_id,student_id,kind,amount_kobo,reference,metadata_json,actor_id) VALUES(?,?,?,?,?,?,?)',[$tid,$t['student_id'],'topup',$t['amount_kobo'],$t['reference'],json_encode(['provider'=>$t['provider'],'bank_reference'=>$bank]),$u['id']]);q('UPDATE dw_accounts SET balance_kobo=balance_kobo+? WHERE tenant_id=? AND student_id=?',[$t['amount_kobo'],$tid,$t['student_id']]);q("UPDATE dw_topups SET status='confirmed',confirmed_by=?,bank_reference=? WHERE tenant_id=? AND id=?",[$u['id'],$bank,$tid,$id]);fnJournal($tid,$t['reference'],'1000','2120',(int)$t['amount_kobo'],'School','School prepaid credit funding');audit('wallet.credit','topup',(string)$id);return 'Verified funding credited once; prepaid liability recorded.';});}
function dw_spend(array $u,int $sid,string $kind,int $item,int $qty,string $reference):string{ix_need($u,'wallet_cashier');$tid=(int)$u['tenant_id'];dw_enabled($tid);sv_own('students',$u,$sid);ix_key($reference);if(!in_array($kind,['meal','invoice'],true)||$qty<1||$qty>20)throw new RuntimeException('Invalid school purchase.');return sv_tx(function()use($u,$tid,$sid,$kind,$item,$qty,$reference){$a=dw_account($tid,$sid);$meta=['kind'=>$kind,'item'=>$item,'quantity'=>$qty];$old=q('SELECT * FROM dw_entries WHERE tenant_id=? AND reference=?',[$tid,$reference])->fetch();if($old){if((int)$old['student_id']!==$sid||$old['metadata_json']!==json_encode($meta)||$old['kind']!=='purchase')throw new RuntimeException('Reference reused with changed content.');return 'Purchase already recorded.';}$c=q('SELECT * FROM dw_controls WHERE tenant_id=? AND student_id=?',[$tid,$sid])->fetch();if(!$c)throw new RuntimeException('Guardian must set a spending policy first.');$guardian=ix_fresh($tid,(int)$c['guardian_id']);if($guardian['role']!=='parent')throw new RuntimeException('Active guardian required.');op_child($guardian,$sid);
if($kind==='meal'){$m=ix_own('dw_menu',$u,$item);if(!$m['active']||!$c['allow_meals'])throw new RuntimeException('Meal spending is not authorized.');$amount=(int)$m['price_kobo']*$qty;$invoice=null;}else{$invoice=sv_own('fn_invoices',$u,$item,true);if((int)$invoice['student_id']!==$sid||!preg_match('/^(STORE-|OPS-MEAL)/',$invoice['reference'])||!$c['allow_store']||$qty!==1)throw new RuntimeException('Only linked school-store/meal invoices are eligible.');$amount=max(0,(int)$invoice['amount_kobo']-(int)$invoice['discount_kobo']+(int)$invoice['penalty_kobo']-(int)$invoice['paid_kobo']);}
$spent=-(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM dw_entries WHERE tenant_id=? AND student_id=? AND kind='purchase' AND created_at>=CURRENT_DATE()",[$tid,$sid]);if($amount<=0||$amount>(int)$a['balance_kobo']||$spent+$amount>(int)$c['daily_limit_kobo'])throw new RuntimeException('Insufficient credits or guardian daily spending limit exceeded.');q('INSERT INTO dw_entries(tenant_id,student_id,kind,amount_kobo,reference,metadata_json,actor_id) VALUES(?,?,?,?,?,?,?)',[$tid,$sid,'purchase',-$amount,$reference,json_encode($meta),$u['id']]);q('UPDATE dw_accounts SET balance_kobo=balance_kobo-? WHERE tenant_id=? AND student_id=?',[$amount,$tid,$sid]);if($invoice){q("INSERT INTO fn_payments(tenant_id,invoice_id,reference,amount_kobo,channel,status,notes,confirmed_by,confirmed_at) VALUES(?,?,?,?,'school_wallet','confirmed',?,?,NOW())",[$tid,$item,$reference,$amount,'Prepaid school purchase',$u['id']]);fnJournal($tid,$reference,'2120','1100',$amount,$invoice['campus'],'Prepaid invoice allocation');fnRefresh($tid,$item);}else fnJournal($tid,$reference,'2120','4100',$amount,'School','Cafeteria prepaid sale');audit('wallet.purchase','student',(string)$sid);return 'School purchase recorded once; no new external cash receipt was counted.';});}
function dw_action(array $u,string $a):string{$tid=(int)$u['tenant_id'];dw_enabled($tid);
if($a==='controls'){if($u['role']!=='parent')throw new RuntimeException('Linked guardian required.');$sid=op_id('student_id');op_child($u,$sid);$limit=op_money(op_text('daily_limit',20,true));q('INSERT INTO dw_controls VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE guardian_id=VALUES(guardian_id),allow_meals=VALUES(allow_meals),allow_store=VALUES(allow_store),daily_limit_kobo=VALUES(daily_limit_kobo)',[$tid,$sid,$u['id'],isset($_POST['allow_meals'])?1:0,isset($_POST['allow_store'])?1:0,$limit]);return 'Guardian spending policy saved.';}
if($a==='topup'){$sid=op_id('student_id');dw_scope($u,$sid);if($u['role']==='student')throw new RuntimeException('Guardian or cashier must initiate funding.');$amount=op_money(op_text('amount',20,true));if($amount<=0)throw new RuntimeException('Positive funding amount required.');$provider=sv_enum('provider',['bank','paystack']);$ref='DW-'.bin2hex(random_bytes(16));q('INSERT INTO dw_topups(tenant_id,student_id,requested_by,amount_kobo,provider,reference) VALUES(?,?,?,?,?,?)',[$tid,$sid,$u['id'],$amount,$provider,$ref]);$id=(int)$GLOBALS['pdo']->lastInsertId();if($provider==='paystack'){$res=fn45Api('POST','/transaction/initialize',fn45Secret($tid),['email'=>$u['email'],'amount'=>$amount,'currency'=>'NGN','reference'=>$ref]);$url=sv_https((string)($res['data']['authorization_url']??''));if(empty($res['status'])||parse_url($url,PHP_URL_HOST)!=='checkout.paystack.com')throw new RuntimeException('Paystack checkout unavailable; pending top-up retained for reconciliation.');q('UPDATE dw_topups SET checkout_url=? WHERE tenant_id=? AND id=?',[$url,$tid,$id]);}return 'Funding request #'.$id.' created; credits are issued only after verification.';}
if($a==='confirm')return dw_credit($u,op_id('topup_id'));
if($a==='menu'){ix_need($u,'wallet_cashier');$p=op_money(op_text('price',20,true));if($p<=0)throw new RuntimeException('Positive price required.');q('INSERT INTO dw_menu(tenant_id,name,price_kobo) VALUES(?,?,?)',[$tid,op_text('name',150,true),$p]);return 'Cafeteria item created.';}
if($a==='spend')return dw_spend($u,op_id('student_id'),sv_enum('kind',['meal','invoice']),op_id('item_id'),sv_qty('quantity',20),ix_key(op_text('reference',100,true)));
if($a==='refund'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');return sv_tx(function()use($u,$tid){$r=ix_own('dw_entries',$u,op_id('entry_id'),true);$m=json_decode($r['metadata_json'],true);if($r['kind']!=='purchase'||($m['kind']??'')!=='meal'||(int)$r['actor_id']===(int)$u['id'])throw new RuntimeException('A different administrator may reverse a cafeteria sale only. Invoice corrections require Finance review.');dw_account($tid,(int)$r['student_id']);$ref='REF-'.$r['reference'];if(g('SELECT id FROM dw_entries WHERE tenant_id=? AND reference=?',[$tid,$ref]))return 'Refund already recorded.';$amount=-(int)$r['amount_kobo'];q('INSERT INTO dw_entries(tenant_id,student_id,kind,amount_kobo,reference,metadata_json,actor_id) VALUES(?,?,?,?,?,?,?)',[$tid,$r['student_id'],'refund',$amount,$ref,json_encode(['original'=>$r['id'],'reason'=>op_text('reason',500,true)]),$u['id']]);q('UPDATE dw_accounts SET balance_kobo=balance_kobo+? WHERE tenant_id=? AND student_id=?',[$amount,$tid,$r['student_id']]);fnJournal($tid,$ref,'4100','2120',$amount,'School','Reviewed cafeteria reversal');return 'Cafeteria credits restored once; no bank refund was initiated.';});}throw new RuntimeException('Unsupported prepaid action.');}
function dw_render(array $u):void{$tid=(int)$u['tenant_id'];op_card('School prepaid credits · NGN');echo '<p>Purpose-limited cafeteria and school-store credits. Guardian spending policy and school activation are required. No cash withdrawals, peer transfers or external merchants. Provider arrangements and applicable regulatory review remain the school’s responsibility.</p>';if(!ix_setting($tid,'wallet_enabled')){echo '<p>Disabled until the school administrator completes review in Access & settings.</p></section>';return;}$cash=ix_can($u,'wallet_cashier');$children=$cash?op_choices(q('SELECT id,name FROM students WHERE tenant_id=?',[$tid])->fetchAll()):sv_children($u);if(!$cash&&!in_array($u['role'],['parent','student'],true))throw new RuntimeException('Wallet access required.');foreach($children as $sid=>$name){echo '<h3>'.e($name).'</h3>';op_table(q('SELECT balance_kobo FROM dw_accounts WHERE tenant_id=? AND student_id=?',[$tid,$sid])->fetchAll(),['Balance (kobo)']);op_table(q('SELECT id,kind,amount_kobo,reference,created_at FROM dw_entries WHERE tenant_id=? AND student_id=? ORDER BY id DESC LIMIT 40',[$tid,$sid])->fetchAll(),['ID','Kind','Kobo','Reference','Time']);$tops=q('SELECT id,amount_kobo,provider,status,checkout_url FROM dw_topups WHERE tenant_id=? AND student_id=? ORDER BY id DESC LIMIT 30',[$tid,$sid])->fetchAll();foreach($tops as &$t){$t['checkout_url']=$t['checkout_url']?'<a href="'.e($t['checkout_url']).'" rel="noopener">Paystack checkout</a>':'';}unset($t);/* URLs are rendered separately, never as raw table HTML. */op_table(array_map(fn($t)=>array_slice($t,0,4),$tops),['Top-up ID','Kobo','Provider','Status']);foreach($tops as $t)if($t['checkout_url'])echo $t['checkout_url'];}
if($u['role']==='parent')ix_form('dw_controls',['student_id'=>['Child',$children],'allow_meals'=>['Allow cafeteria purchases','check'],'allow_store'=>['Allow school store / meal invoice settlement','check'],'daily_limit'=>['Daily spending limit (₦)','number']],'Save guardian policy');if($u['role']!=='student')ix_form('dw_topup',['student_id'=>['Student',$children],'amount'=>['Funding amount (₦)','number'],'provider'=>['Funding',['bank'=>'Bank transfer: independent receipt verification','paystack'=>'Paystack: exact verified NGN transaction']]],'Request funding');if($u['role']!=='student')ix_form('dw_confirm',['topup_id'=>['Top-up ID','number'],'bank_reference'=>['Actual unique bank reference (bank funding only)','text','',false]],'Verify funding');if($cash){op_table(q('SELECT id,name,price_kobo,active FROM dw_menu WHERE tenant_id=?',[$tid])->fetchAll(),['Menu ID','Item','Kobo','Active']);ix_form('dw_menu',['name'=>['Cafeteria item','text'],'price'=>['Unit price (₦)','number']],'Create item');ix_form('dw_spend',['student_id'=>['Student',$children],'kind'=>['School purchase',['meal'=>'Cafeteria menu item','invoice'=>'School store / meal invoice']],'item_id'=>['Menu item / invoice ID','number'],'quantity'=>['Quantity (invoice: 1)','number','1'],'reference'=>['Unique sale reference','text','SALE-'.bin2hex(random_bytes(8))]],'Record approved school purchase');if($u['role']==='school_admin')ix_form('dw_refund',['entry_id'=>['Cafeteria purchase entry ID','number'],'reason'=>['Reviewed reversal reason','textarea']],'Restore cafeteria credits');}echo '</section>';}
